import React, { useState } from 'react';
import { 
  Container, Row, Col, Card, Form, 
  Alert, Table, Badge, Spinner, Button 
} from 'react-bootstrap';
import { useNotification } from '../contexts/NotificationContext';

const SBUSearchPage = () => {
  const [keyword, setKeyword] = useState('');
  const [searchType, setSearchType] = useState('nama');
  const [loading, setLoading] = useState(false);
  const [results, setResults] = useState([]);
  const [stats, setStats] = useState({ total: 0, active: 0, expired: 0 });
  const { showNotification } = useNotification();

  const searchSBU = async (keyword, type = 'nama') => {
    try {
      const response = await fetch(
        `http://localhost:5000/api/lpjk/sbu/search?keyword=${encodeURIComponent(keyword)}&type=${type}`
      );
      return await response.json();
    } catch (error) {
      throw error;
    }
  };

  const handleSearch = async (e) => {
    e.preventDefault();
    if (!keyword.trim()) {
      showNotification('Masukkan keyword pencarian', 'warning');
      return;
    }

    setLoading(true);
    try {
      const response = await searchSBU(keyword, searchType);
      
      if (response.status === 'success') {
        setResults(response.data);
        calculateStats(response.data);
        showNotification(`Ditemukan ${response.total} data SBU`, 'success');
      } else {
        showNotification(response.message, 'error');
      }
    } catch (error) {
      console.error('Search error:', error);
      showNotification('Gagal melakukan pencarian', 'error');
      // Fallback demo data
      setResults(generateDemoData());
      showNotification('Menampilkan data demo', 'info');
    } finally {
      setLoading(false);
    }
  };

  const calculateStats = (data) => {
    const total = data.length;
    const active = data.filter(item => item.status === 'AKTIF').length;
    const expired = data.filter(item => item.status === 'EXPIRED').length;
    setStats({ total, active, expired });
  };

  const generateDemoData = () => {
    return [
      {
        id_sbu: 'WIKA001',
        nama_perusahaan: 'PT WIJAYA KARYA (PERSERO) Tbk.',
        npwp: '01.525.221.8-092.000',
        alamat: 'Jl. D.I. Panjaitan Kav. 9, Cawang',
        kota: 'Jakarta Timur',
        provinsi: 'DKI Jakarta',
        telepon: '(021) 8583111',
        email: 'corsec@wika.co.id',
        kualifikasi: 'KONTRAKTOR',
        klasifikasi: 'BESAR',
        bidang_usaha: 'JASA PELAKSANA KONSTRUKSI',
        sub_bidang: 'BANGUNAN SIPIL',
        no_sertifikat: 'S-002/LPJK/I/2023',
        tgl_terbit: '01 Januari 2023',
        tgl_expired: '31 Desember 2025',
        masa_berlaku: '01 Januari 2023 - 31 Desember 2025',
        status: 'AKTIF',
        grade: '7',
        nilai_kontrak: 'Rp 45.000.000.000',
        url_detail: 'https://lpjk.pu.go.id/search-badan-usaha-detail/WIKA001',
        sumber: 'LPJK PU (Demo Data)',
        is_demo_data: true
      }
    ];
  };

  const handleExport = async () => {
    try {
      const response = await fetch(
        `http://localhost:5000/api/lpjk/sbu/export?keyword=${encodeURIComponent(keyword)}&type=${searchType}`,
        { method: 'GET' }
      );
      
      if (response.ok) {
        const blob = await response.blob();
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `sbu-${keyword}-${searchType}.csv`;
        document.body.appendChild(a);
        a.click();
        a.remove();
        showNotification('Data berhasil diexport', 'success');
      }
    } catch (error) {
      showNotification('Gagal mengexport data', 'error');
    }
  };

  const handleClear = () => {
    setKeyword('');
    setResults([]);
    setStats({ total: 0, active: 0, expired: 0 });
  };

  return (
    <Container className="py-4">
      <Row className="mb-4">
        <Col>
          <h1 className="display-6 fw-bold">
            <i className="fas fa-certificate me-2"></i>
            Pencarian SBU (LPJK)
          </h1>
          <p className="text-muted">
            Cari data Sertifikat Badan Usaha dari LPJK berdasarkan nama atau NPWP
          </p>
        </Col>
      </Row>

      {/* Search Form */}
      <Row className="mb-4">
        <Col lg={8}>
          <Card className="shadow-sm">
            <Card.Body>
              <Form onSubmit={handleSearch}>
                <Row>
                  <Col md={6}>
                    <Form.Group className="mb-3">
                      <Form.Label>
                        <i className="fas fa-search me-1"></i>
                        Kata Kunci
                      </Form.Label>
                      <Form.Control
                        type="text"
                        placeholder="Masukkan nama perusahaan atau NPWP"
                        value={keyword}
                        onChange={(e) => setKeyword(e.target.value)}
                        disabled={loading}
                      />
                    </Form.Group>
                  </Col>
                  <Col md={4}>
                    <Form.Group className="mb-3">
                      <Form.Label>
                        <i className="fas fa-filter me-1"></i>
                        Jenis Pencarian
                      </Form.Label>
                      <Form.Select
                        value={searchType}
                        onChange={(e) => setSearchType(e.target.value)}
                        disabled={loading}
                      >
                        <option value="nama">Nama Perusahaan</option>
                        <option value="npwp">NPWP</option>
                      </Form.Select>
                    </Form.Group>
                  </Col>
                  <Col md={2} className="d-flex align-items-end">
                    <Button
                      type="submit"
                      variant="primary"
                      className="w-100"
                      disabled={loading || !keyword.trim()}
                    >
                      {loading ? (
                        <>
                          <Spinner
                            as="span"
                            animation="border"
                            size="sm"
                            role="status"
                            aria-hidden="true"
                            className="me-2"
                          />
                          Mencari...
                        </>
                      ) : (
                        <>
                          <i className="fas fa-search me-1"></i>
                          Cari
                        </>
                      )}
                    </Button>
                  </Col>
                </Row>
              </Form>
            </Card.Body>
          </Card>
        </Col>
        <Col lg={4}>
          <Card className="shadow-sm h-100">
            <Card.Body className="d-flex flex-column">
              <h6 className="card-title">
                <i className="fas fa-info-circle me-1"></i>
                Informasi
              </h6>
              <div className="mt-auto">
                <div className="d-flex justify-content-between mb-2">
                  <span className="text-muted">Total Data:</span>
                  <Badge bg="info">{stats.total}</Badge>
                </div>
                <div className="d-flex justify-content-between mb-2">
                  <span className="text-muted">Aktif:</span>
                  <Badge bg="success">{stats.active}</Badge>
                </div>
                <div className="d-flex justify-content-between">
                  <span className="text-muted">Kadaluarsa:</span>
                  <Badge bg="warning">{stats.expired}</Badge>
                </div>
              </div>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Results */}
      {results.length > 0 && (
        <Row className="mb-4">
          <Col>
            <Card className="shadow-sm">
              <Card.Header className="bg-light d-flex justify-content-between align-items-center">
                <div>
                  <i className="fas fa-list me-2"></i>
                  Hasil Pencarian ({results.length} data)
                </div>
                <div>
                  <Button
                    variant="success"
                    size="sm"
                    onClick={handleExport}
                    disabled={results.length === 0}
                    title="Export ke CSV"
                  >
                    <i className="fas fa-download me-1"></i>
                    Export
                  </Button>
                  <Button
                    variant="outline-danger"
                    size="sm"
                    className="ms-2"
                    onClick={handleClear}
                  >
                    <i className="fas fa-trash me-1"></i>
                    Clear
                  </Button>
                </div>
              </Card.Header>
              <Card.Body className="p-0">
                <Table responsive hover className="mb-0">
                  <thead className="table-light">
                    <tr>
                      <th>No</th>
                      <th>Nama Perusahaan</th>
                      <th>NPWP</th>
                      <th>Kualifikasi</th>
                      <th>Klasifikasi</th>
                      <th>Bidang Usaha</th>
                      <th>Status</th>
                      <th>Grade</th>
                      <th>Detail</th>
                    </tr>
                  </thead>
                  <tbody>
                    {results.map((item, index) => (
                      <tr key={index}>
                        <td>{index + 1}</td>
                        <td>
                          <strong>{item.nama_perusahaan}</strong>
                          <div className="small text-muted">
                            {item.kota}, {item.provinsi}
                          </div>
                        </td>
                        <td>
                          <code>{item.npwp}</code>
                        </td>
                        <td>{item.kualifikasi}</td>
                        <td>
                          <Badge bg={
                            item.klasifikasi === 'BESAR' ? 'primary' :
                            item.klasifikasi === 'MENENGAH' ? 'info' : 'secondary'
                          }>
                            {item.klasifikasi}
                          </Badge>
                        </td>
                        <td>
                          <div className="small">
                            {item.bidang_usaha}
                            {item.sub_bidang && (
                              <div className="text-muted">
                                <small>{item.sub_bidang}</small>
                              </div>
                            )}
                          </div>
                        </td>
                        <td>
                          <Badge bg={item.status === 'AKTIF' ? 'success' : 'danger'}>
                            {item.status}
                          </Badge>
                          {item.masa_berlaku && (
                            <div className="small text-muted mt-1">
                              {item.masa_berlaku}
                            </div>
                          )}
                        </td>
                        <td>
                          <Badge bg="warning" className="grade-badge">
                            Grade {item.grade}
                          </Badge>
                        </td>
                        <td>
                          <Button
                            variant="outline-primary"
                            size="sm"
                            onClick={() => window.open(item.url_detail, '_blank')}
                            title="Lihat detail di LPJK"
                          >
                            <i className="fas fa-external-link-alt"></i>
                          </Button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </Table>
              </Card.Body>
              {results[0]?.is_demo_data && (
                <Card.Footer className="bg-warning bg-opacity-10">
                  <div className="text-warning">
                    <i className="fas fa-exclamation-triangle me-2"></i>
                    Data demo - Cloudflare protection aktif di LPJK. 
                    <a 
                      href={`https://lpjk.pu.go.id/pencarian-bu-index?key=${keyword}`} 
                      target="_blank" 
                      rel="noreferrer"
                      className="ms-2"
                    >
                      Kunjungi LPJK langsung
                    </a>
                  </div>
                </Card.Footer>
              )}
            </Card>
          </Col>
        </Row>
      )}

      {/* Empty State */}
      {!loading && results.length === 0 && keyword && (
        <Row>
          <Col>
            <Alert variant="info" className="text-center">
              <i className="fas fa-info-circle fa-2x mb-3"></i>
              <h5>Tidak ada data ditemukan</h5>
              <p>Coba dengan keyword lain atau gunakan pencarian berdasarkan NPWP</p>
            </Alert>
          </Col>
        </Row>
      )}

      {/* Tips */}
      <Row className="mt-4">
        <Col>
          <Card className="shadow-sm">
            <Card.Header className="bg-light">
              <i className="fas fa-lightbulb me-2"></i>
              Tips Pencarian SBU
            </Card.Header>
            <Card.Body>
              <Row>
                <Col md={4}>
                  <div className="d-flex mb-3">
                    <div className="flex-shrink-0">
                      <i className="fas fa-building text-primary"></i>
                    </div>
                    <div className="flex-grow-1 ms-3">
                      <h6>Nama Perusahaan</h6>
                      <p className="small text-muted mb-0">
                        Gunakan nama lengkap perusahaan atau singkatan yang umum
                      </p>
                    </div>
                  </div>
                </Col>
                <Col md={4}>
                  <div className="d-flex mb-3">
                    <div className="flex-shrink-0">
                      <i className="fas fa-id-card text-success"></i>
                    </div>
                    <div className="flex-grow-1 ms-3">
                      <h6>NPWP</h6>
                      <p className="small text-muted mb-0">
                        Masukkan NPWP lengkap dengan format XX.XXX.XXX.X-XXX.XXX
                      </p>
                    </div>
                  </div>
                </Col>
                <Col md={4}>
                  <div className="d-flex mb-3">
                    <div className="flex-shrink-0">
                      <i className="fas fa-filter text-warning"></i>
                    </div>
                    <div className="flex-grow-1 ms-3">
                      <h6>Filter Hasil</h6>
                      <p className="small text-muted mb-0">
                        Lihat status sertifikat dan grade untuk evaluasi vendor
                      </p>
                    </div>
                  </div>
                </Col>
              </Row>
            </Card.Body>
          </Card>
        </Col>
      </Row>
    </Container>
  );
};

export default SBUSearchPage;